(function(){
  CardSpoke_MODS.register('story-studio-expansion', {
    meta: {
      name: 'Story Studio Expansion',
      type: 'Expansion',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Story beats timeline overlay for narrative work',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onAppInit(){
      const rail = document.createElement('div');
      rail.className = 'ss-rail';
      const labels = ['Hook','Inciting','Rising','Midpoint','Climax','Aftermath'];
      labels.forEach((label, i) => {
        const beat = document.createElement('div');
        beat.className = 'ss-beat';
        beat.style.setProperty('--beat-index', i);
        const tag = document.createElement('span');
        tag.className = 'ss-label';
        tag.textContent = label;
        beat.appendChild(tag);
        rail.appendChild(beat);
      });
      document.body.appendChild(rail);
    },
    onDisable(){
      const rail = document.querySelector('.ss-rail');
      if(rail) rail.remove();
    }
  });
})();
